// Le message part vers Telegram, qui l'interprete comme du Markdown. Un texte
// d'erreur contient a peu pres toujours un caractere de balisage — apostrophe,
// tiret bas, asterisque, accent grave, crochet — et Telegram repond alors 400
// « can't parse entities ». L'alerte se perd, et la panne devient invisible.
//
// On neutralise donc ce qui vient du moteur, et on borne la longueur : au-dela
// de 4096 caracteres Telegram refuse aussi, et une pile d'appels depasse vite.
function neutraliser(valeur) {
  return String(valeur == null ? '' : valeur)
    .replace(/[_*`\[\]()~>#+=|{}.!\\-]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

const e = $json.execution || {};
const w = $json.workflow || {};
const err = e.error || {};

const nomWorkflow = neutraliser(w.name || 'inconnu');
const nomNoeud = neutraliser(e.lastNodeExecuted || err.node?.name || 'inconnu');
const texteErreur = neutraliser(err.message || 'sans message');

// ETRANGLEMENT DES REPETITIONS.
//
// Une panne ne se produit presque jamais une seule fois : une tache
// quart-horaire qui echoue produit 96 executions dans la journee, donc 96
// alertes identiques — et les vraies pannes se perdent dedans.
//
// Ce filtre existait auparavant dans `Signaler l echec`, cote sous-workflow
// « Envoyer reponse client », ou il ne servait a rien : n8n ne persiste la
// memoire statique qu au terme d une execution REUSSIE, et ce noeud-la se
// termine par un `throw`. Ici l execution reussit, donc la memoire tient.
//
// On ne se tait pas pour autant completement : la 1re, la 10e et la 100e
// occurrence du jour passent, en annoncant leur rang. Une panne qui dure reste
// visible, sans occuper le canal.
const PALIERS = [1, 10, 100];
const cle = [nomWorkflow, nomNoeud, texteErreur.slice(0, 120)].join('|');
const jour = new Date().toLocaleDateString('fr-CA', { timeZone: 'Africa/Abidjan' });

const sd = $getWorkflowStaticData('global');
if (sd.jour !== jour) { sd.jour = jour; sd.compte = {}; }
if (!sd.compte) sd.compte = {};

const rang = (sd.compte[cle] || 0) + 1;
sd.compte[cle] = rang;

// Rien a envoyer : sans item, le noeud Telegram ne s execute pas et
// l execution se termine en succes — ce qui est precisement la condition pour
// que le compteur ci-dessus soit conserve.
if (!PALIERS.includes(rang)) return [];

const horodatage = new Date().toLocaleString('fr-FR', {
  timeZone: 'Africa/Abidjan',
  day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit',
});

const lignes = [
  'ALERTE WORKFLOW',
  '',
  'Workflow : ' + nomWorkflow,
  'Noeud : ' + nomNoeud,
  'Erreur : ' + texteErreur.slice(0, 500),
  'Heure : ' + horodatage,
];

// Le rang n apparait qu a partir de la 10e : sur une panne isolee il n aurait
// rien dit, et l alerte doit rester breve.
if (rang > 1) {
  lignes.push('', 'Repetition numero ' + rang + ' aujourd hui pour cette meme erreur');
}

if (e.url) lignes.push('', String(e.url));

return [{ json: { message: lignes.join('\n').slice(0, 3800) } }];
